import json
from ast import parse, dump

def parse_nested_parens(paren_string: str) -> List[int]:
    parsed_paren_list = list(map(str, parse(paren_string, mode='eval').body))
    nesting_levels = []

    for parentheses_group in parsed_paren_list:
        nesting_level = 0
        for i in range(len(parentheses_group)):
            if parentheses_group[i] == '(':
                nesting_level += 1
            elif parentheses_group[i] == ')':
                nesting_level -= 1
            if nesting_level > max(nesting_levels):
                nesting_levels.append(nesting_level)

    return nesting_levels
